Lemma fi_fast : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t1 t2 s0 a0 a1 a3 a7 s2 s3 s4 s6 s7 s8 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp D : Z) (vbs : list byte) (T0 A6 A2 A4 : Z),
  (7 - j = k)%nat -> (j <= 7)%nat ->
  bytes_at bsegs m1 vp vbs -> accessible m1 vp (Z.of_nat (length vbs)) -> mem_inv bsegs m1 -> ACONST m1 ->
  vp <= D -> D + 7 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
